package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.time.LocalDate;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class LateFeeIntegrationTest {

    private static final LocalDate LOANED_AT = LocalDate.of(2026, 1, 1);
    private static final String DUE_AT = "2026-01-15";

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void returning_on_the_due_date_has_no_late_fee() throws Exception {
        String loanId = loanOn(LOANED_AT, "Due Day Book");

        assertReturn(loanId, "2026-01-15", 0, 0);
    }

    @Test
    void returning_one_day_late_charges_100() throws Exception {
        String loanId = loanOn(LOANED_AT, "One Day Late Book");

        assertReturn(loanId, "2026-01-16", 1, 100);
    }

    @Test
    void returning_five_days_late_charges_500() throws Exception {
        String loanId = loanOn(LOANED_AT, "Five Days Late Book");

        assertReturn(loanId, "2026-01-20", 5, 500);
    }

    @Test
    void loan_without_loanedAt_starts_today_and_due_date_is_fourteen_days_later() throws Exception {
        String bookId = registerBook("Today Loan Book");
        String memberId = registerMember("오지훈");

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"bookId\":\"" + bookId + "\",\"memberId\":\"" + memberId + "\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.loanedAt").value(LocalDate.now().toString()))
                .andExpect(jsonPath("$.dueAt").value(LocalDate.now().plusDays(14).toString()));
    }

    @Test
    void return_without_body_uses_today_and_reports_overdue_days() throws Exception {
        String loanId = loanOn(LocalDate.now().minusDays(20), "No Body Return Book");

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.returnedAt").value(LocalDate.now().toString()))
                .andExpect(jsonPath("$.overdueDays").value(6))
                .andExpect(jsonPath("$.lateFee").value(600));
    }

    @Test
    void return_with_empty_json_body_uses_today() throws Exception {
        String loanId = loanOn(LocalDate.now(), "Empty Body Return Book");

        mockMvc.perform(post("/loans/{loanId}/return", loanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.returnedAt").value(LocalDate.now().toString()))
                .andExpect(jsonPath("$.overdueDays").value(0))
                .andExpect(jsonPath("$.lateFee").value(0));
    }

    @Test
    void returning_before_the_loan_date_returns_400() throws Exception {
        String loanId = loanOn(LOANED_AT, "Early Return Book");

        mockMvc.perform(post("/loans/{loanId}/return", loanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2025-12-31\"}"))
                .andExpect(status().isBadRequest());
    }

    private void assertReturn(String loanId, String returnedAt, int overdueDays, int lateFee) throws Exception {
        mockMvc.perform(post("/loans/{loanId}/return", loanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"" + returnedAt + "\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanId").value(loanId))
                .andExpect(jsonPath("$.returnedAt").value(returnedAt))
                .andExpect(jsonPath("$.overdueDays").value(overdueDays))
                .andExpect(jsonPath("$.lateFee").value(lateFee));
    }

    private String loanOn(LocalDate loanedAt, String title) throws Exception {
        String bookId = registerBook(title);
        String memberId = registerMember("회원-" + title);
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"bookId\":\"" + bookId + "\",\"memberId\":\"" + memberId
                                + "\",\"loanedAt\":\"" + loanedAt + "\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.dueAt").value(loanedAt.plusDays(14).toString()))
                .andReturn().getResponse().getContentAsString();
        JsonNode loan = objectMapper.readTree(loaned);
        return loan.get("loanId").asText();
    }

    private String registerMember(String name) throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"" + name + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    private String registerBook(String title) throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }
}
EOF
